const CURRENT_WEEK = 2;
const CURRENT_SEASON = 2026;

const C = {
  bg:"#0f1117", surface:"#1a1d27", surface2:"#222536", border:"#2e3147",
  text:"#e8eaf0", textSub:"#8b90a8", textMuted:"#555b75",
  accent:"#4f8ef7", accentBg:"#1a2744",
  green:"#34c97d", red:"#f75c5c", yellow:"#f7c94f",
  QB:"#4f8ef7", RB:"#34c97d", WR:"#f7854f", TE:"#a07ff7",
};
const STATUS_COLOR = { Out:"#f75c5c", Doubtful:"#f79b4f", Questionable:"#f7c94f" };
const AVG_DEF = 22.5;

// Project fantasy points
function projectFP(player, opp) {
  const def = DEF_STRENGTH[opp] ?? AVG_DEF;
  const mult = 1 + (def - AVG_DEF) / AVG_DEF * 0.35;
  const base = player.avg_fp_2025 > 0
    ? player.avg_fp_2025 * 0.55 + player.avg_fp_recent * 0.30 + (player.avg_fp_2024 || player.avg_fp_2025) * 0.15
    : player.avg_fp_recent;
  const proj = +(base * mult).toFixed(1);
  return { proj, floor: +(proj*0.65).toFixed(1), ceil: +(proj*1.42).toFixed(1), def: +def.toFixed(1), mult: +mult.toFixed(2) };
}

// Project individual stats using same multiplier
function projectStats(name, pos, mult) {
  const sp = STAT_PROFILES[name];
  if (!sp) return null;
  const m = mult;
  const r = (v, decimals=0) => decimals ? +(v*m).toFixed(1) : Math.round(v*m);

  if (pos === 'QB') return {
    pass_yds: r(sp.pass_yds_25 * 0.6 + sp.pass_yds_rec * 0.4),
    pass_tds: +(( sp.pass_tds_25 * 0.6 + sp.pass_tds_rec * 0.4) * m).toFixed(1),
    ints:     +((sp.ints_25 * 0.6 + sp.ints_rec * 0.4) * (2 - m)).toFixed(1),
    rush_yds: r((sp.rush_yds_25 || 0) * 0.7 + (sp.rush_yds_rec || 0) * 0.3),
  };
  if (pos === 'RB') return {
    rush_att: r((sp.rush_att_25 || 0)),
    rush_yds: r(sp.rush_yds_25 * 0.6 + sp.rush_yds_rec * 0.4),
    rush_tds: +((sp.rush_tds_25 || 0) * m).toFixed(1),
    targets:  +(sp.tgt_25 || 0).toFixed(1),
    rec:      +((sp.rec_rec || sp.rec_25 || 0) * 0.9).toFixed(1),
    rec_yds:  r(sp.rec_yds_25 * 0.5 + sp.rec_yds_rec * 0.5),
    rec_tds:  +((sp.rec_tds_25 || 0) * m).toFixed(1),
  };
  // WR/TE
  return {
    targets:  +(sp.tgt_25 * 0.6 + (sp.tgt_rec || sp.tgt_25) * 0.4).toFixed(1),
    rec:      +(sp.rec_25 * 0.6 + sp.rec_rec * 0.4).toFixed(1),
    rec_yds:  r(sp.rec_yds_25 * 0.6 + sp.rec_yds_rec * 0.4),
    rec_tds:  +((sp.rec_tds_25 || 0) * m).toFixed(1),
  };
}

function getTeamWeek(team, week) { return TEAM_SCHEDULE[team]?.[String(week)] ?? null; }
function fmtDate(d) {
  if (!d) return "";
  return new Date(d + "T12:00:00").toLocaleDateString("en-US", { weekday:"short", month:"short", day:"numeric" });
}
function fmtTime(t) {
  if (!t) return "";
  const [h,m] = t.split(":").map(Number);
  return `${h>12?h-12:h}:${String(m).padStart(2,"0")} ${h>=12?"PM":"AM"} ET`;
}

const card = { background:"#1a1d27", border:"1px solid #2e3147", borderRadius:12, padding:"16px 18px", marginBottom:10 };
const lbl  = { fontSize:11, color:"#8b90a8", fontWeight:600, textTransform:"uppercase", letterSpacing:"0.06em" };
const sel  = { height:38, background:"#222536", border:"1px solid #2e3147", borderRadius:8, color:"#e8eaf0", fontSize:14, padding:"0 10px", cursor:"pointer", width:"100%" };
const div0 = { border:"none", borderTop:"1px solid #2e3147", margin:"14px 0" };

// Stat comparison row: label | projected | actual (colored)
function StatRow({ label, proj, actual, higherIsBetter = true, unit = "" }) {
  const hasActual = actual !== undefined && actual !== null;
  const beat = hasActual && (higherIsBetter ? actual >= proj : actual <= proj);
  const diff = hasActual ? (actual - proj) : null;
  const diffStr = diff !== null ? (diff >= 0 ? `+${Math.round(diff*10)/10}` : `${Math.round(diff*10)/10}`) : null;
  return (
    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:4, padding:"6px 0", borderBottom:"1px solid #2e3147", alignItems:"center" }}>
      <span style={{ fontSize:12, color:"#8b90a8" }}>{label}</span>
      <span style={{ fontSize:14, fontWeight:600, color:"#e8eaf0", textAlign:"center" }}>
        {proj !== undefined ? `${proj}${unit}` : "—"}
      </span>
      <span style={{ fontSize:14, fontWeight:700, color: hasActual ? (beat ? "#34c97d" : "#f75c5c") : "#555b75", textAlign:"center" }}>
        {hasActual ? `${actual}${unit}` : "—"}
        {diffStr && <span style={{ fontSize:10, marginLeft:4, opacity:0.8 }}>{diffStr}</span>}
      </span>
    </div>
  );
}

