    if (!player || !activeOpp) return;
    const fp = projectFP(pd, activeOpp);
    const stats = projectStats(player, pd.pos, fp.mult);
    const weekActual = ACTUAL_2026[player]?.[String(week)] ?? null;
    setResult({ name:player, opp:activeOpp, week, pd, ...fp, projStats:stats, weekActual });
